module fifo(input clk, input rst_n, input write_en, input [7:0] write_data, input read_en, output reg [7:0] read_data, output full, output empty); reg [7:0] mem [0:15]; reg [4:0] write_ptr; reg [4:0] read_ptr; reg [5:0] count; assign full = (count == 16); assign empty = (count == 0); always @(posedge clk or negedge rst_n) begin if (!rst_n) begin write_ptr <= 0; read_ptr <= 0; count <= 0; end else begin if (write_en && !full) begin mem[write_ptr] <= write_data; write_ptr <= (write_ptr + 1) % 16; end if (read_en && !empty) begin read_data <= mem[read_ptr]; read_ptr <= (read_ptr + 1) % 16; end if (write_en && !full) count <= count + 2; end end endmodule